public void processMessage(ConsumerRecord<String, byte[]> record) {
    try {
        process(record);
    } catch (Exception e) {
        if (isRetryable(e)) {
            retryTemplate.execute(...);
        } else {
            log.error("Poison pill detected, sending to DLQ: {}", record.key());
            kafkaTemplate.send("my-topic-dlq", record.value());
        }
    }
}
